const String masterInvoiceTemplate = r'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Tax Invoice Template</title>
<style>
/* ===================== PRINT / PAGE CSS ===================== */
@page { size: A4 portrait; margin: 0; }
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; background: #e4e4e4; }
.controls { background: #fff; padding: 10px 14px; display: flex; flex-wrap: wrap; gap: 14px; align-items: center; font-size: 13px; border-bottom: 1px solid #bbb; }
.controls label { display: flex; gap: 6px; align-items: center; }
.controls input[type=number] { width: 90px; }
.controls button { padding: 6px 16px; cursor: pointer; }
.sheet { width: 210mm; min-height: 297mm; margin: 10px auto; background: #fff; padding: 5mm; display: flex; flex-direction: column; }
.frame { flex: 1; border: 1.2px solid #222; display: flex; flex-direction: column; padding: 2mm; gap: 2mm; }
@media print {
  body { background: #fff; }
  .controls { display: none !important; }
  .sheet { margin: 0; box-shadow: none; }
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
/* ===================== INVOICE STYLES ===================== */
.hdr { display: grid; grid-template-columns: 38mm 1fr 45mm; gap: 3mm; align-items: stretch; border-bottom: 1px solid #222; padding-bottom: 2mm; min-height: 25mm; }
.hdr .logo { display: flex; align-items: center; justify-content: center; }
.hdr .logo img { width: 100%; max-width: 36mm; height: auto; max-height: 25mm; object-fit: contain; display: block; }
.hdr .co { text-align: center; align-self: center; }
.hdr .co h1 { margin: 0 0 1mm; font-size: 24.5px; letter-spacing: .3px; text-transform: uppercase; font-weight: bold; }
.hdr .co .addr { font-size: 12.5px; line-height: 1.35; }
.hdr .co .ct { font-size: 12px; margin-top: 1mm; }
.hdr .right-col { display: flex; flex-direction: column; gap: 1.5mm; justify-content: center; align-self: center; }
.hdr .copy-box { border: 1px solid #777; border-radius: 2mm; font-size: 10.5px; font-weight: bold; text-align: center; padding: 1.1mm 1mm; background: #fff; letter-spacing: 0.5px; }
.hdr .gst { border: 1px solid #777; border-radius: 2mm; font-size: 12px; display: flex; flex-direction: column; text-align: center; height: max-content; align-self: center; overflow: hidden; width: 100%; box-sizing: border-box; }
.hdr .gst .date { font-weight: bold; font-size: 13px; border-bottom: 1px dashed #777; padding: 2mm 1mm; background: #f0f0f0; }
.hdr .gst .gstin { padding: 1.5mm 1mm; line-height: 1.3; }
.hdr .gst .gstin b { display: block; }
.title { background: #737373; color: #fff; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; padding: 1.2mm 3mm; }
.title .t { font-size: 20px; font-weight: bold; text-align: center; letter-spacing: 1px; line-height: 1.15; }
.title .t .copy-label { display: block; font-size: 13.2px; font-weight: bold; letter-spacing: 0.5px; margin-top: 1.0mm; }
.row2 { display: grid; grid-template-columns: 1fr 1.25fr; gap: 2mm; }
.box { border: 1px solid #222; border-radius: 2mm; overflow: hidden; }
.box h3 { margin: 0; background: #737373; color: #fff; font-size: 12.5px; padding: 1.2mm 3mm; letter-spacing: .5px; }
.kv { display: grid; grid-template-columns: 26mm 4mm 1fr; font-size: 12.5px; padding: 1.2mm 3mm; border-bottom: 1px solid #ccc; line-height: 1.3; }
.kv:last-child { border-bottom: 0; }
.kv .k { font-weight: bold; } .kv .v { word-break: break-word; }
.kv .v .bn { font-size: 15px; }
.kv.gs .v { font-weight: bold; }
.itemwrap { flex: 1; border: 1.2px solid #222; min-height: 60mm; display: flex; position: relative;
  /* full-height column lines (SR | DESCRIPTION | HSN | QTY | RATE | AMOUNT) */
  background-image: linear-gradient(#222,#222), linear-gradient(#222,#222), linear-gradient(#222,#222), linear-gradient(#222,#222), linear-gradient(#222,#222);
  background-size: 1px 100%; background-repeat: no-repeat;
  background-position: 8% 0, 48% 0, 59% 0, 70% 0, calc(100% - 38mm) 0; }
table.items { width: 100%; height: 100%; table-layout: fixed; border-collapse: collapse; font-size: 13.5px; }
.items th { background: #737373; color: #fff; padding: 1.6mm 1mm; font-size: 12.8px; line-height: 1.2; border: 1px solid #222; border-top: 0; }
.items td { padding: 1.5mm 1.8mm; vertical-align: top; border: 0; }
.items tr.prod td { border-bottom: 1px solid #777; }
.items th:first-child { border-left: 0; }
.items th:last-child { border-right: 0; }
.items .c { text-align: center; } .items .r { text-align: right; }
.items .pn { font-weight: bold; font-size: 14px; }
.items .ds { white-space: pre-wrap; word-break: break-word; margin-top: .6mm; }
.items .po { margin-top: .6mm; font-size: 12.8px; }
.items tr.fill td { height: 100%; padding: 0; border-bottom: 0; }
.bottom { display: grid; grid-template-columns: 47% 1fr; gap: 2mm; align-items: stretch; }
.col { display: flex; flex-direction: column; gap: 2mm; }
.parcel { border: 1px solid #222; border-radius: 2mm; display: grid; grid-template-columns: 30mm 1fr; font-size: 12.5px; }
.parcel div { padding: 1.8mm 3mm; } .parcel div:first-child { font-weight: bold; border-right: 1px solid #222; }
.terms { flex: 1; } .terms ol { margin: 0; padding: 1.5mm 3mm 1.5mm 8mm; font-size: 11.5px; line-height: 1.4; }
.terms li { margin-bottom: 1mm; }
.tot { border: 1px solid #222; border-radius: 2mm; overflow: hidden; }
.tot .tr { display: grid; grid-template-columns: 1fr 38mm; font-size: 13.8px; border-bottom: 1px solid #222; }
.tot .tr span { padding: 2.1mm 3mm; text-align: center; display: flex; align-items: center; justify-content: center; } 
.tot .tr span + span { border-left: 1px solid #222; }
.tot .tax-area { display: flex; flex-direction: column; height: 15.5mm; border-bottom: 1px solid #222; }
.tot .tax-area .tr { flex: 1; border-bottom: 0; }
.tot .tax-area .tr:not(:last-child) { border-bottom: 1px solid #222; }
.tot .tax-area .tr span { display: flex; align-items: center; justify-content: center; padding: 0 3mm; text-align: center; }
.tot .tax-area .tr span + span { justify-content: center; }
.tot .tr.sb span:first-child { font-weight: bold; }
.tot .gt { background: #737373; color: #fff; font-weight: bold; border-bottom: 0; }
.tot .gt span { padding: 3mm 3mm; font-size: 15px; }
.tot .gt span + span { font-size: 16px; }
.words { border: 1px solid #222; border-radius: 2mm; display: grid; grid-template-columns: 23mm 1fr; font-size: 14px; padding: 3.3mm 3mm; gap: 2mm; align-items: center; }
.sign { position: relative; z-index: 1; flex: 1; border: 1px solid #222; border-radius: 2mm; text-align: center; padding: 2mm; display: flex; flex-direction: column; justify-content: space-between; min-height: 36mm; overflow: hidden; }
.sign .cn { position: relative; z-index: 2; font-weight: bold; font-size: 13px; text-transform: uppercase; }
.sign img { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); max-height: 25mm; max-width: 45mm; opacity: 0.12; z-index: -1; }
.sign .as { position: relative; z-index: 2; border-top: 1px dashed #222; padding-top: 1mm; font-size: 12.5px; }
.foot { text-align: center; font-size: 11px; color: #444; }
</style>
</head>
<body>

<!-- Production HTML Template -->
<div class="sheet"><div class="frame" id="invoice"></div></div>

<script>
/* =====================================================================
   1. CONFIG — company-level display details. Flutter can replace these.
   ===================================================================== */
const LOGO_DATA_URI = "data:image/jpeg;base64,";
const CONFIG = {
  companyName: "ARUN MENSWARE SERVICE",
  addressLines: ["Laxmi Chhaya Society-1, Plot No 177, 25 Mtr,", "150 Feet Ring Road, Rajkot, Gujarat - 360005."],
  phone: "+91 - 9824417257",
  email: "Arunmsws@gmail.com",
  gstin: "24AKZPP9424E1ZM",
  logoSrc: LOGO_DATA_URI,       // embedded ARUN logo (data URI) - replace with Flutter-supplied data URI if needed
  signatureSrc: LOGO_DATA_URI,  // image shown in signature box
  bank: { name: "HDFC RAJKOT", account: "03792000003498", ifsc: "HDFC0000379", email: "Arunmsws@gmail.com" },
  terms: [
    "Interest @ 21% will be charged if payment is not made within 10 days.",
    "We will not be responsible for loss of the materials when it leaves our premises.",
    "Payment by A/c Payee Cheque/Draft Only.",
    "Subject To Rajkot Jurisdiction Only. E & O.E."
  ]
};


/* =====================================================================
   3. UTILITIES + 5. NUMBER FORMATTING
   ===================================================================== */
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const r2 = n => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const money = n => "₹ " + Number(n).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtAmt = n => Number(n).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtQty = n => Number(n).toLocaleString("en-IN", { maximumFractionDigits: 3 });   // number only, never the unit
const fmtDate = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d || ""); return m ? `${m[3]}/${m[2]}/${m[1]}` : (d || "-"); };
const dash = v => (v && String(v).trim()) ? esc(v) : "-";

/* =====================================================================
   6. AMOUNT IN WORDS (Indian Rupees)
   ===================================================================== */
const ONES = ["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
const TENS = ["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
const below100 = n => n < 20 ? ONES[n] : TENS[Math.floor(n / 10)] + (n % 10 ? " " + ONES[n % 10] : "");
const below1000 = n => (n >= 100 ? ONES[Math.floor(n / 100)] + " Hundred" + (n % 100 ? " " : "") : "") + (n % 100 ? below100(n % 100) : "");
function intWords(n) {
  if (n === 0) return "Zero";
  const parts = [[10000000, "Crore"], [100000, "Lakh"], [1000, "Thousand"]];
  let out = [];
  for (const [v, name] of parts) { const q = Math.floor(n / v); if (q) { out.push(intWords(q) + " " + name); n %= v; } }
  if (n) out.push(below1000(n));
  return out.join(" ");
}
function amountInWords(amount) {
  const total = Math.round(amount * 100), rupees = Math.floor(total / 100), paise = total % 100;
  return "Rupees " + intWords(rupees) + (paise ? " and " + below100(paise) + " Paise" : "") + " Only";
}

/* =====================================================================
   4. TAX / TOTAL CALCULATION
   ===================================================================== */

// Used by the renderer: recomputes totals from the invoice fields.
function computeTotals(inv) {
  const itemTotal = r2(inv.items.reduce((s, i) => s + i.quantity * i.rate, 0));
  const subtotal = r2(itemTotal + (inv.otherExp || 0));
  const grandTotal = r2(subtotal + (inv.cgst || 0) + (inv.sgstAmount || 0) + (inv.igst || 0) + (inv.roundOff || 0));
  return { subtotal, grandTotal };
}
const pct = (part, sub) => sub ? String(parseFloat((part / sub * 100).toFixed(2))) + "%" : "";

/* =====================================================================
   7. INVOICE RENDERER  (dynamic values are marked with {{field}} comments)
   ===================================================================== */
function renderInvoice(inv) {
  const { subtotal, grandTotal } = computeTotals(inv);
  const words = amountInWords(grandTotal);                                   // {{amountInWords}}
  const isDup = inv.invoiceType === "duplicate";                             // {{invoiceType}}
  const copy = isDup ? "(DUPLICATE)" : "(ORIGINAL FOR RECIPIENT)";

  const rows = inv.items.map((i, n) => `
    <tr class="prod">
      <td class="c">${n + 1}</td>
      <td>
        <div class="pn">${esc(i.productName)}</div>
        ${i.description ? `<div class="ds">${esc(i.description)}</div>` : ""}
        ${(i.poAllocations && i.poAllocations.length ? i.poAllocations.map(p => p.poNo) : (i.poId ? [i.poId] : []))
            .filter(Boolean).map(p => `<div class="po">PO: <b>${esc(p)}</b></div>`).join("")}
      </td>
      <td class="c">${esc(i.hsnCode)}</td>
      <td class="c">${fmtQty(i.quantity)}</td>
      <td class="c">${fmtAmt(i.rate)}</td>
      <td class="c"><b>${fmtAmt(i.quantity * i.rate)}</b></td>
    </tr>`).join("");

  const taxRows = [];
  if (inv.cgst > 0 || inv.sgstAmount > 0) {
    taxRows.push(`<div class="tr"><span>ADD. CGST ${pct(inv.cgst, subtotal)}</span><span>${money(inv.cgst)}</span></div>`);
    taxRows.push(`<div class="tr"><span>ADD. SGST ${pct(inv.sgstAmount, subtotal)}</span><span>${money(inv.sgstAmount)}</span></div>`);
  }
  if (inv.igst > 0) taxRows.push(`<div class="tr"><span>ADD. IGST ${pct(inv.igst, subtotal)}</span><span>${money(inv.igst)}</span></div>`);

  const lr = [inv.lrNo, inv.lrDate].filter(x => x && String(x).trim());
  const C = CONFIG;

  document.getElementById("invoice").innerHTML = `
  <div class="hdr">
    <div class="logo"><img src="${esc(C.logoSrc)}" alt=""></div>
    <div class="co">
      <h1>${esc(C.companyName)}</h1>
      <div class="addr">${C.addressLines.map(esc).join("<br>")}</div>
      <div class="ct">${esc(C.phone)} &nbsp;|&nbsp; ${esc(C.email)}</div>
    </div>
    <div class="gst"><b>GSTIN :</b>${esc(C.gstin)}</div>
  </div>

  <div class="title"><span></span><div class="t">TAX INVOICE<small>${copy}</small></div><span></span></div>

  <div class="row2">
    <div class="box">
      <div class="kv"><span class="k">Invoice No</span><span>:</span><span class="v">${dash(inv.invoiceNo)}</span></div>
      <div class="kv"><span class="k">Invoice Date</span><span>:</span><span class="v">${fmtDate(inv.invoiceDate)}</span></div>
      <div class="kv"><span class="k">Challan No</span><span>:</span><span class="v">${dash(inv.challanNo)}</span></div>
      <div class="kv"><span class="k">Transport By</span><span>:</span><span class="v">${dash(inv.transportBy)}</span></div>
      <div class="kv"><span class="k">LR No / Date</span><span>:</span><span class="v">${lr.length ? lr.map(esc).join(" &nbsp;/&nbsp; ") : "-"}</span></div>
    </div>
    <div class="box">
      <h3>BUYER DETAILS</h3>
      <div class="kv"><span class="k">M/s</span><span>:</span><span class="v"><b>${dash(inv.buyerName)}</b></span></div>
      <div class="kv"><span class="k">Address</span><span>:</span><span class="v" style="white-space:pre-line">${dash(inv.buyerAddress)}</span></div>
      <div class="kv gs"><span class="k">GSTIN</span><span>:</span><span class="v">${dash(inv.buyerGstin)}</span></div>
    </div>
  </div>

  <div class="itemwrap">
    <table class="items">
      <colgroup><col style="width:8%"><col style="width:40%"><col style="width:11%"><col style="width:11%"><col style="width:auto"><col style="width:38mm"></colgroup>
      <thead><tr><th>SR<br>No.</th><th>DESCRIPTION OF GOODS</th><th>HSN<br>Code</th><th>QTY.</th><th>RATE<br>(₹)</th><th>AMOUNT<br>(₹)</th></tr></thead>
      <tbody>${rows}<tr class="fill"><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody>
    </table>
  </div>

  <div class="bottom">
    <div class="col">
      <div class="parcel"><div>PARCEL NO. :</div><div style="text-align: center;">${dash(inv.parcelNo)}</div></div>
      <div class="box">
        <h3>BANK DETAILS</h3>
        <div class="kv"><span class="k">Bank Name</span><span>:</span><span class="v">${esc(C.bank.name)}</span></div>
        <div class="kv"><span class="k">Bank Account</span><span>:</span><span class="v">${esc(C.bank.account)}</span></div>
        <div class="kv"><span class="k">IFSC</span><span>:</span><span class="v">${esc(C.bank.ifsc)}</span></div>
        <div class="kv"><span class="k">Email</span><span>:</span><span class="v">${esc(C.bank.email)}</span></div>
      </div>
      <div class="box terms">
        <h3>TERMS &amp; CONDITIONS</h3>
        <ol>${C.terms.map(t => `<li>${esc(t)}</li>`).join("")}</ol>
      </div>
    </div>
    <div class="col">
      <div class="tot">
        <div class="tr"><span>OTHER EXP.</span><span>${money(inv.otherExp || 0)}</span></div>
        <div class="tr sb"><span>SUB TOTAL</span><span>${money(subtotal)}</span></div>
        ${taxRows.join("")}
        ${inv.roundOff ? `<div class="tr"><span>ROUND OFF</span><span>${inv.roundOff < 0 ? "- " : "+ "}₹ ${fmtAmt(Math.abs(inv.roundOff))}</span></div>` : ""}
        <div class="tr gt"><span>GRAND TOTAL</span><span>${money(grandTotal)}</span></div>
      </div>
      <div class="words"><b>In Words :</b><span>${esc(words)}</span></div>
      <div class="sign">
        <div class="cn">${esc(C.companyName)}</div>
        ${C.signatureSrc ? `<img src="${esc(C.signatureSrc)}" alt="">` : ""}
        <div class="as">Authorised Signature</div>
      </div>
    </div>
  </div>
  <div class="foot">This is a computer generated invoice.</div>`;
}

/* =====================================================================
   8. RENDER INVOICE FROM FLUTTER
   ===================================================================== */
if (window.INVOICE_DATA) {
  if (window.INVOICE_DATA.seller) {
    const s = window.INVOICE_DATA.seller;
    if (s.name) CONFIG.companyName = s.name;
    if (s.address) CONFIG.addressLines = s.address.split('\n');
    if (s.phone) CONFIG.phone = s.phone;
    if (s.email) CONFIG.email = s.email;
    if (s.gstin) CONFIG.gstin = s.gstin;
    if (s.logoDataUri) CONFIG.logoSrc = s.logoDataUri;
    if (s.signatureDataUri) CONFIG.signatureSrc = s.signatureDataUri || s.logoDataUri;
    if (s.bankName) CONFIG.bank.name = s.bankName;
    if (s.accountNo) CONFIG.bank.account = s.accountNo;
    if (s.ifsc) CONFIG.bank.ifsc = s.ifsc;
    if (s.bankEmail) CONFIG.bank.email = s.bankEmail;
    if (s.termsAndConditions) CONFIG.terms = s.termsAndConditions;
  }
  renderInvoice(window.INVOICE_DATA);
}
</script>
</body>
</html>
''';